'use client';

import {
  useEffect,
  useId,
  useRef,
  type KeyboardEvent,
  type ReactNode,
} from 'react';
import './slide-over-sheet.css';

export interface SlideOverSheetProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: ReactNode;
  /**
   * By default the sheet covers the viewport. Set this to keep it inside the
   * nearest ancestor with `position: relative`.
   */
  contained?: boolean;
  className?: string;
}

const FOCUSABLE =
  'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])';

/**
 * A panel that slides in from the right. Focus moves into it when it opens,
 * stays inside while it is open, and returns to the opener when it closes.
 * Escape and the backdrop both close it.
 */
export function SlideOverSheet({
  open,
  onClose,
  title,
  children,
  contained = false,
  className = '',
}: SlideOverSheetProps) {
  const panel = useRef<HTMLDivElement>(null);
  const titleId = useId();

  useEffect(() => {
    if (!open) return;
    const opener = document.activeElement as HTMLElement | null;
    panel.current?.focus();
    return () => opener?.focus?.();
  }, [open]);

  const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === 'Escape') {
      event.stopPropagation();
      onClose();
      return;
    }
    if (event.key !== 'Tab' || !panel.current) return;
    const focusable = Array.from(
      panel.current.querySelectorAll<HTMLElement>(FOCUSABLE)
    );
    if (focusable.length === 0) {
      event.preventDefault();
      return;
    }
    const first = focusable[0];
    const last = focusable[focusable.length - 1];
    const current = document.activeElement;
    if (event.shiftKey && (current === first || current === panel.current)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && current === last) {
      event.preventDefault();
      first.focus();
    }
  };

  return (
    <div
      className={`mg-sheet ${className}`}
      data-open={open}
      data-contained={contained}
    >
      <div className='mg-sheet__backdrop' onClick={onClose} />
      <div
        ref={panel}
        role='dialog'
        aria-modal='true'
        aria-labelledby={titleId}
        tabIndex={-1}
        className='mg-sheet__panel'
        onKeyDown={onKeyDown}
      >
        <div className='mg-sheet__header'>
          <h2 id={titleId} className='mg-sheet__title'>
            {title}
          </h2>
          <button
            type='button'
            className='mg-sheet__close'
            aria-label='Close'
            onClick={onClose}
          >
            ×
          </button>
        </div>
        <div className='mg-sheet__body'>{children}</div>
      </div>
    </div>
  );
}

.mg-sheet {
  position: fixed;
  inset: 0;
  z-index: 50;
  overflow: hidden;
  /* Hidden content cannot be focused or read while the sheet is closed. */
  visibility: hidden;
  transition: visibility 0s 320ms;
}

.mg-sheet[data-contained='true'] {
  position: absolute;
}

.mg-sheet[data-open='true'] {
  visibility: visible;
  transition-delay: 0s;
}

.mg-sheet__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(12, 23, 56, 0.45);
  opacity: 0;
  transition: opacity 320ms ease;
}

.mg-sheet[data-open='true'] .mg-sheet__backdrop {
  opacity: 1;
}

.mg-sheet__panel {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  width: min(320px, 86%);
  background: #fff;
  box-shadow: -18px 0 40px -20px rgba(12, 23, 56, 0.5);
  color: var(--mg-ink, #0c1738);
  transform: translateX(100%);
  transition: transform 320ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.mg-sheet[data-open='true'] .mg-sheet__panel {
  transform: translateX(0);
}

.mg-sheet__panel:focus {
  outline: none;
}

.mg-sheet__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 12px 12px 18px;
  border-bottom: 1px solid var(--mg-line, #d6def2);
}

.mg-sheet__title {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
}

.mg-sheet__close {
  width: 44px;
  height: 44px;
  border: 0;
  border-radius: 8px;
  background: none;
  color: inherit;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
}

.mg-sheet__close:hover {
  background: var(--mg-foam, #f5f8ff);
}

.mg-sheet__close:focus-visible,
.mg-sheet__body :focus-visible {
  outline: 2px solid var(--mg-accent, #164cff);
  outline-offset: 2px;
}

.mg-sheet__body {
  flex: 1;
  overflow: auto;
  padding: 16px 18px;
  color: #46527a;
}

@media (prefers-reduced-motion: reduce) {
  /* Fade instead of sliding. */
  .mg-sheet__panel {
    opacity: 0;
    transform: none;
    transition: opacity 160ms linear;
  }
  .mg-sheet[data-open='true'] .mg-sheet__panel {
    opacity: 1;
  }
  .mg-sheet,
  .mg-sheet__backdrop {
    transition-duration: 0s, 160ms;
    transition-delay: 160ms, 0s;
  }
  .mg-sheet[data-open='true'] {
    transition-delay: 0s;
  }
}
